<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {request,run} from '../../api/client';import {ElMessageBox,ElMessage} from 'element-plus';
const fieldLabels:Record<string,string>={baseUrl:'基础地址',username:'用户名',testPath:'测试路径',testMethod:'测试方法',host:'主机',password:'密码',token:'访问令牌',privateKey:'SSH私钥',passphrase:'SSH私钥口令',connectTimeout:'连接超时',readTimeout:'读写超时',secretHeaders:'秘密请求头'};
const certs=ref<any[]>([]),rows=ref<any[]>([]),form=ref<any>(null),json=ref(''),result=ref('');async function load(){rows.value=await request('/servers')}onMounted(()=>run(async()=>{await load();certs.value=await request('/certificates?owner=CUSTOMER')}));
const authFields=computed(()=>{const c=form.value?.config;if(!c)return [];if(form.value.type==='SFTP')return c.authType==='KEY'?['privateKey','passphrase']:['password'];return c.authType==='BASIC'?['username','password']:c.authType==='BEARER'?['token']:[]});
const clearFields=computed(()=>[...authFields.value.filter(f=>f!=='username'),...(form.value?.type==='HTTP'?['secretHeaders']:[])]);
function edit(r?:any){run(async()=>{form.value=r?await request('/servers/'+r.id):{alias:'',type:'HTTP',description:'',enabled:true,config:{baseUrl:'',authType:'NONE',testPath:'/',testMethod:'HEAD',headers:{},trustAssetIds:[],connectTimeout:10,readTimeout:30,clearSecrets:[]}};form.value.config.clearSecrets=[];json.value=JSON.stringify({headers:form.value.config.headers||{},secretHeaders:{},testCodes:form.value.config.testCodes||[200]},null,2)})}
function defaults(){form.value.config=form.value.type==='HTTP'?{baseUrl:'https://',authType:'NONE',headers:{},secretHeaders:{},testPath:'/',testMethod:'GET',testCodes:[200],trustAssetIds:[],connectTimeout:10,readTimeout:30}:{host:'',port:22,username:'',authType:'PASSWORD',connectTimeout:10,readTimeout:30};json.value=JSON.stringify({headers:form.value.config.headers||{},secretHeaders:{},testCodes:form.value.config.testCodes||[200]},null,2)}
function save(){run(async()=>{await request('/servers'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',form.value);form.value=null;await load();ElMessage.success('已保存')})}function test(r:any){run(async()=>{result.value=await request('/servers/'+r.id+'/test','POST').then(x=>(x.success?'连接测试成功':'连接测试失败：'+x.message)+'，耗时 '+x.elapsedMs+' ms')})}async function remove(r:any){try{await ElMessageBox.confirm('删除服务器 '+r.alias+'？','确认')}catch{return}run(async()=>{await request('/servers/'+r.id,'DELETE');await load()})}
</script>
<template><div class="page-heading"><h1>服务器管理</h1><el-button type="primary" @click="edit()">新增服务器</el-button></div><div class="panel"><el-table :data="rows"><el-table-column prop="alias" label="别名"/><el-table-column prop="type" label="协议"/><el-table-column label="地址" min-width="180" show-overflow-tooltip><template #default="{row}">{{row.type==='HTTP'?row.config.baseUrl:row.config.host+':'+(row.config.port||22)}}</template></el-table-column><el-table-column prop="enabled" label="启用"/><el-table-column prop="description" label="说明"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link @click="test(row)">测试</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><pre v-if="result">{{result}}</pre></div><el-dialog :model-value="!!form" @close="form=null" title="服务器配置" width="760px"><el-form v-if="form" label-position="top"><el-form-item label="唯一别名"><el-input v-model="form.alias"/></el-form-item><el-form-item label="协议"><el-select v-model="form.type" :disabled="!!form.id" @change="defaults"><el-option label="HTTPS / HTTP" value="HTTP"/><el-option label="SFTP" value="SFTP"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item><el-switch v-model="form.enabled" active-text="启用"/><el-alert title="已保存的凭据留空保留，勾选清除后保存才会移除。" :closable="false"/><el-form-item v-for="f in (form.type==='HTTP'?['baseUrl','testPath','testMethod']:['host','username'])" :key="f" :label="fieldLabels[f]||f"><el-input v-model="form.config[f]"/></el-form-item><el-form-item label="认证方式"><el-select v-model="form.config.authType"><el-option v-for="a in (form.type==='HTTP'?['NONE','BASIC','BEARER']:['PASSWORD','KEY'])" :key="a" :value="a"/></el-select></el-form-item><el-form-item v-if="form.type==='SFTP'" label="端口"><el-input-number v-model="form.config.port" :min="1" :max="65535"/></el-form-item><el-form-item v-for="f in authFields" :key="f" :label="fieldLabels[f]+(form.config[f+'Configured']?'（已配置，留空保留）':'')"><el-input v-model="form.config[f]" :type="f==='privateKey'?'textarea':f==='username'?'text':'password'" :rows="4" :show-password="f!=='privateKey'&&f!=='username'" autocomplete="new-password"/></el-form-item><el-form-item v-for="f in ['connectTimeout','readTimeout']" :key="f" :label="fieldLabels[f]+'（秒）'"><el-input-number v-model="form.config[f]" :min="1" :max="300"/></el-form-item><el-form-item v-if="clearFields.length" label="明确清除已保存凭据（勾选后保存生效）"><el-checkbox-group v-model="form.config.clearSecrets"><el-checkbox v-for="f in clearFields" :key="f" :value="f">清除 {{fieldLabels[f]}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item v-if="form.type==='HTTP'" label="信任的客户证书"><el-select v-model="form.config.trustAssetIds" multiple filterable style="width:100%"><el-option v-for="c in certs" :key="c.id" :value="c.id" :label="[c.commonName||c.name,c.customer,c.serial].filter(Boolean).join(' · ')"/></el-select></el-form-item><el-form-item v-if="form.type==='HTTP'" label="HTTP 请求头、秘密请求头、测试状态码 JSON（编辑后应用）"><el-input v-model="json" type="textarea" :rows="8" spellcheck="false"/><el-button @click="run(async()=>{Object.assign(form.config,JSON.parse(json))})">应用 JSON</el-button><el-button @click="json=JSON.stringify({headers:form.config.headers||{},secretHeaders:{},testCodes:form.config.testCodes||[200]},null,2)">读取当前字段</el-button></el-form-item><el-button @click="defaults">填入协议默认字段</el-button></el-form><template #footer><el-button @click="form=null">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>




